\set ON_ERROR_STOP on

SET client_encoding = 'UTF8';

BEGIN;

-- Tablas y datos del respaldo de MySQL. Ejecutar en la base vacia marazul_sucre.

CREATE TABLE "buyers" (
  "id_buyer" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 4),
  "document_type" varchar(15) NOT NULL,
  "document" varchar(25) NOT NULL,
  "legal_name" varchar(150) NOT NULL,
  "phone" varchar(25) DEFAULT NULL,
  "email" varchar(254) DEFAULT NULL,
  PRIMARY KEY ("id_buyer"),
  CONSTRAINT "buyers_uq_buyer_document" UNIQUE ("document_type","document"),
  CHECK ("id_buyer" BETWEEN 0 AND 4294967295)
);

CREATE SEQUENCE "catch_audit_id_catch_audit_seq" START WITH 1;

CREATE TABLE "catch_audit" (
  "id_catch_audit" numeric(20,0) NOT NULL DEFAULT nextval('catch_audit_id_catch_audit_seq'),
  "id_catch" bigint NOT NULL,
  "change_date" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "db_user" varchar(288) NOT NULL,
  "operation" varchar(10) NOT NULL,
  "previous_data" jsonb DEFAULT NULL,
  "new_data" jsonb NOT NULL,
  PRIMARY KEY ("id_catch_audit"),
  CONSTRAINT "ck_catch_audit_operation" CHECK (("operation" in ('INSERT','UPDATE'))),
  CHECK ("id_catch_audit" BETWEEN 0 AND 18446744073709551615),
  CHECK ("id_catch" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "catches" (
  "id_catch" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 201),
  "id_trip" bigint NOT NULL,
  "id_species" bigint NOT NULL,
  "landing_date" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "weight_kg" decimal(12,3) NOT NULL,
  "piece_count" bigint NOT NULL,
  "average_size_cm" decimal(7,2) DEFAULT NULL,
  "available_weight_kg" decimal(12,3) NOT NULL DEFAULT '0.000',
  PRIMARY KEY ("id_catch"),
  CONSTRAINT "ck_catch_availability" CHECK ((("available_weight_kg" >= 0) and ("available_weight_kg" <= "weight_kg"))),
  CONSTRAINT "ck_catch_pieces" CHECK (("piece_count" > 0)),
  CONSTRAINT "ck_catch_size" CHECK ((("average_size_cm" is null) or ("average_size_cm" > 0))),
  CONSTRAINT "ck_catch_weight" CHECK (("weight_kg" > 0)),
  CHECK ("id_catch" BETWEEN 0 AND 4294967295),
  CHECK ("id_trip" BETWEEN 0 AND 4294967295),
  CHECK ("id_species" BETWEEN 0 AND 4294967295),
  CHECK ("piece_count" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "fishermen" (
  "id_fisherman" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 7),
  "document" varchar(25) NOT NULL,
  "first_names" varchar(80) NOT NULL,
  "last_names" varchar(80) NOT NULL,
  "phone" varchar(25) DEFAULT NULL,
  "active" smallint NOT NULL DEFAULT '1',
  PRIMARY KEY ("id_fisherman"),
  CONSTRAINT "fishermen_uq_fisherman_document" UNIQUE ("document"),
  CONSTRAINT "ck_fisherman_active" CHECK (("active" in (0,1))),
  CHECK ("id_fisherman" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "fishing_zones" (
  "id_zone" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 4),
  "name" varchar(120) NOT NULL,
  "description" varchar(500) DEFAULT NULL,
  PRIMARY KEY ("id_zone"),
  CHECK ("id_zone" BETWEEN 0 AND 4294967295)
);

CREATE SEQUENCE "inventory_movements_id_movement_seq" START WITH 11;

CREATE TABLE "inventory_movements" (
  "id_movement" numeric(20,0) NOT NULL DEFAULT nextval('inventory_movements_id_movement_seq'),
  "id_lot" bigint NOT NULL,
  "id_source_warehouse" bigint DEFAULT NULL,
  "id_destination_warehouse" bigint DEFAULT NULL,
  "id_responsible" bigint NOT NULL,
  "weight_kg" decimal(12,3) NOT NULL,
  "movement_date" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id_movement"),
  CONSTRAINT "ck_movement_route" CHECK (((("id_source_warehouse" is not null) or ("id_destination_warehouse" is not null)) and (("id_source_warehouse" is null) or ("id_destination_warehouse" is null) or ("id_source_warehouse" <> "id_destination_warehouse")))),
  CONSTRAINT "ck_movement_weight" CHECK (("weight_kg" > 0)),
  CHECK ("id_movement" BETWEEN 0 AND 18446744073709551615),
  CHECK ("id_lot" BETWEEN 0 AND 4294967295),
  CHECK ("id_source_warehouse" BETWEEN 0 AND 4294967295),
  CHECK ("id_destination_warehouse" BETWEEN 0 AND 4294967295),
  CHECK ("id_responsible" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "organization_fisherman" (
  "id_membership" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 7),
  "id_organization" bigint NOT NULL,
  "id_fisherman" bigint NOT NULL,
  "join_date" date NOT NULL,
  "leave_date" date DEFAULT NULL,
  PRIMARY KEY ("id_membership"),
  CONSTRAINT "organization_fisherman_id_organization" UNIQUE ("id_organization","id_fisherman","join_date"),
  CONSTRAINT "ck_membership_dates" CHECK ((("leave_date" is null) or ("leave_date" >= "join_date"))),
  CHECK ("id_membership" BETWEEN 0 AND 4294967295),
  CHECK ("id_organization" BETWEEN 0 AND 4294967295),
  CHECK ("id_fisherman" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "organization_vessel" (
  "id_vessel_link" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 3),
  "id_organization" bigint NOT NULL,
  "id_vessel" bigint NOT NULL,
  "start_date" date NOT NULL,
  "end_date" date DEFAULT NULL,
  PRIMARY KEY ("id_vessel_link"),
  CONSTRAINT "organization_vessel_id_organization" UNIQUE ("id_organization","id_vessel","start_date"),
  CONSTRAINT "ck_link_dates" CHECK ((("end_date" is null) or ("end_date" >= "start_date"))),
  CHECK ("id_vessel_link" BETWEEN 0 AND 4294967295),
  CHECK ("id_organization" BETWEEN 0 AND 4294967295),
  CHECK ("id_vessel" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "organizations" (
  "id_organization" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 2),
  "tax_id" varchar(25) NOT NULL,
  "name" varchar(150) NOT NULL,
  "phone" varchar(25) DEFAULT NULL,
  PRIMARY KEY ("id_organization"),
  CONSTRAINT "organizations_uq_organization_tax_id" UNIQUE ("tax_id"),
  CHECK ("id_organization" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "product_classifications" (
  "id_classification" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 3),
  "name" varchar(80) NOT NULL,
  "description" varchar(300) DEFAULT NULL,
  PRIMARY KEY ("id_classification"),
  CONSTRAINT "product_classifications_uq_classification_name" UNIQUE ("name"),
  CHECK ("id_classification" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "product_lots" (
  "id_lot" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 11),
  "id_catch" bigint NOT NULL,
  "id_classification" bigint NOT NULL,
  "lot_code" varchar(40) NOT NULL,
  "initial_weight_kg" decimal(12,3) NOT NULL,
  "classification_date" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY ("id_lot"),
  CONSTRAINT "product_lots_uq_lot_code" UNIQUE ("lot_code"),
  CONSTRAINT "ck_lot_weight" CHECK (("initial_weight_kg" > 0)),
  CHECK ("id_lot" BETWEEN 0 AND 4294967295),
  CHECK ("id_catch" BETWEEN 0 AND 4294967295),
  CHECK ("id_classification" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "quality_inspections" (
  "id_inspection" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 21),
  "id_catch" bigint NOT NULL,
  "control_date" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "temperature_c" decimal(4,1) NOT NULL,
  "freshness_level" varchar(10) NOT NULL,
  PRIMARY KEY ("id_inspection"),
  CONSTRAINT "ck_inspection_freshness" CHECK (("freshness_level" in ('EXCELENTE','ACEPTABLE','RECHAZADO'))),
  CONSTRAINT "ck_inspection_temperature" CHECK (("temperature_c" between -(5.0) and 15.0)),
  CHECK ("id_inspection" BETWEEN 0 AND 4294967295),
  CHECK ("id_catch" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "roles" (
  "id_role" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 4),
  "role_name" varchar(50) NOT NULL,
  "description" varchar(250) DEFAULT NULL,
  PRIMARY KEY ("id_role"),
  CONSTRAINT "roles_uq_role_name" UNIQUE ("role_name"),
  CHECK ("id_role" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "sale_details" (
  "id_detail" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 168),
  "id_sale" bigint NOT NULL,
  "id_catch" bigint NOT NULL,
  "sold_weight_kg" decimal(12,3) NOT NULL,
  "unit_price" decimal(12,2) NOT NULL,
  PRIMARY KEY ("id_detail"),
  CONSTRAINT "sale_details_uq_detail_sale_catch" UNIQUE ("id_sale","id_catch"),
  CONSTRAINT "ck_detail_price" CHECK (("unit_price" > 0)),
  CONSTRAINT "ck_detail_weight" CHECK (("sold_weight_kg" > 0)),
  CHECK ("id_detail" BETWEEN 0 AND 4294967295),
  CHECK ("id_sale" BETWEEN 0 AND 4294967295),
  CHECK ("id_catch" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "sales" (
  "id_sale" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 49),
  "id_buyer" bigint NOT NULL,
  "sale_date" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "id_commercial_manager" bigint NOT NULL,
  PRIMARY KEY ("id_sale"),
  CHECK ("id_sale" BETWEEN 0 AND 4294967295),
  CHECK ("id_buyer" BETWEEN 0 AND 4294967295),
  CHECK ("id_commercial_manager" BETWEEN 0 AND 4294967295)
);

CREATE SEQUENCE "sales_audit_id_audit_seq" START WITH 1;

CREATE TABLE "sales_audit" (
  "id_audit" numeric(20,0) NOT NULL DEFAULT nextval('sales_audit_id_audit_seq'),
  "change_date" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "db_user" varchar(288) NOT NULL,
  "id_detail" bigint NOT NULL,
  "previous_weight" decimal(12,3) NOT NULL,
  "new_weight" decimal(12,3) NOT NULL,
  "previous_price" decimal(12,2) NOT NULL,
  "new_price" decimal(12,2) NOT NULL,
  PRIMARY KEY ("id_audit"),
  CHECK ("id_audit" BETWEEN 0 AND 18446744073709551615),
  CHECK ("id_detail" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "sales_staff" (
  "id_staff" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 3),
  "document" varchar(25) NOT NULL,
  "first_names" varchar(80) NOT NULL,
  "last_names" varchar(80) NOT NULL,
  "active" smallint NOT NULL DEFAULT '1',
  PRIMARY KEY ("id_staff"),
  CONSTRAINT "sales_staff_uq_staff_document" UNIQUE ("document"),
  CONSTRAINT "ck_staff_active" CHECK (("active" in (0,1))),
  CHECK ("id_staff" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "species" (
  "id_species" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 5),
  "common_name" varchar(100) NOT NULL,
  "scientific_name" varchar(150) NOT NULL,
  "minimum_size_cm" decimal(7,2) NOT NULL,
  PRIMARY KEY ("id_species"),
  CONSTRAINT "species_uq_species_scientific" UNIQUE ("scientific_name"),
  CONSTRAINT "ck_species_size" CHECK (("minimum_size_cm" >= 0)),
  CHECK ("id_species" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "trip_crew" (
  "id_trip_crew" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 121),
  "id_trip" bigint NOT NULL,
  "id_fisherman" bigint NOT NULL,
  "role_on_board" varchar(20) NOT NULL DEFAULT 'TRIPULANTE',
  PRIMARY KEY ("id_trip_crew"),
  CONSTRAINT "trip_crew_id_trip" UNIQUE ("id_trip","id_fisherman"),
  CONSTRAINT "ck_crew_role" CHECK (("role_on_board" in ('RESPONSABLE','TRIPULANTE'))),
  CHECK ("id_trip_crew" BETWEEN 0 AND 4294967295),
  CHECK ("id_trip" BETWEEN 0 AND 4294967295),
  CHECK ("id_fisherman" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "trip_observations" (
  "id_observation" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 41),
  "id_trip" bigint NOT NULL,
  "date_time" timestamp without time zone NOT NULL,
  "description" text NOT NULL,
  PRIMARY KEY ("id_observation"),
  CHECK ("id_observation" BETWEEN 0 AND 4294967295),
  CHECK ("id_trip" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "trips" (
  "id_trip" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 41),
  "id_organization" bigint NOT NULL,
  "id_coordinator" bigint NOT NULL,
  "id_vessel" bigint NOT NULL,
  "id_zone" bigint NOT NULL,
  "departure_date" date NOT NULL,
  "departure_time" time NOT NULL,
  "return_date" date DEFAULT NULL,
  "arrival_time" time DEFAULT NULL,
  "status" varchar(15) NOT NULL DEFAULT 'PLANIFICADA',
  PRIMARY KEY ("id_trip"),
  CONSTRAINT "ck_trip_completed" CHECK ((("status" <> 'FINALIZADA') or ("return_date" is not null))),
  CONSTRAINT "ck_trip_dates" CHECK (((("return_date" is null) and ("arrival_time" is null)) or (("return_date" is not null) and ("arrival_time" is not null) and (("return_date" + "arrival_time") >= ("departure_date" + "departure_time"))))),
  CONSTRAINT "ck_trip_status" CHECK (("status" in ('PLANIFICADA','EN_CURSO','FINALIZADA','CANCELADA'))),
  CHECK ("id_trip" BETWEEN 0 AND 4294967295),
  CHECK ("id_organization" BETWEEN 0 AND 4294967295),
  CHECK ("id_coordinator" BETWEEN 0 AND 4294967295),
  CHECK ("id_vessel" BETWEEN 0 AND 4294967295),
  CHECK ("id_zone" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "users" (
  "id_user" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 1),
  "username" varchar(80) NOT NULL,
  "password_hash" varchar(255) NOT NULL,
  "status" varchar(10) NOT NULL DEFAULT 'INACTIVE',
  "id_role" bigint NOT NULL,
  "id_staff" bigint NOT NULL,
  PRIMARY KEY ("id_user"),
  CONSTRAINT "users_uq_user_username" UNIQUE ("username"),
  CONSTRAINT "users_uq_user_staff" UNIQUE ("id_staff"),
  CONSTRAINT "ck_user_status" CHECK (("status" in ('ACTIVE','INACTIVE'))),
  CHECK ("id_user" BETWEEN 0 AND 4294967295),
  CHECK ("id_role" BETWEEN 0 AND 4294967295),
  CHECK ("id_staff" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "vessels" (
  "id_vessel" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 3),
  "registration" varchar(40) NOT NULL,
  "name" varchar(100) NOT NULL,
  "cargo_capacity_kg" decimal(12,3) NOT NULL,
  "autonomy_category" varchar(25) NOT NULL DEFAULT 'BAJAMAR',
  PRIMARY KEY ("id_vessel"),
  CONSTRAINT "vessels_uq_vessel_registration" UNIQUE ("registration"),
  CONSTRAINT "ck_vessel_capacity" CHECK (("cargo_capacity_kg" > 0)),
  CONSTRAINT "ck_vessel_category" CHECK (("autonomy_category" in ('BAJAMAR','ARTESANAL_INTERMEDIA','ALTAMAR'))),
  CHECK ("id_vessel" BETWEEN 0 AND 4294967295)
);

CREATE TABLE "warehouses" (
  "id_warehouse" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (START WITH 2),
  "id_organization" bigint NOT NULL,
  "name" varchar(100) NOT NULL,
  "location" varchar(200) NOT NULL,
  PRIMARY KEY ("id_warehouse"),
  CONSTRAINT "warehouses_uq_warehouse_name" UNIQUE ("id_organization","name"),
  CHECK ("id_warehouse" BETWEEN 0 AND 4294967295),
  CHECK ("id_organization" BETWEEN 0 AND 4294967295)
);

