INSERT INTO "warehouses" VALUES (1,1,E'Acopio costero',E'Tolú');

-- Las claves foraneas se crean despues de cargar todas las tablas.

ALTER TABLE "catch_audit" ADD CONSTRAINT "fk_catch_audit" FOREIGN KEY ("id_catch") REFERENCES "catches" ("id_catch") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "catches" ADD CONSTRAINT "fk_catch_species" FOREIGN KEY ("id_species") REFERENCES "species" ("id_species") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "catches" ADD CONSTRAINT "fk_catch_trip" FOREIGN KEY ("id_trip") REFERENCES "trips" ("id_trip") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "inventory_movements" ADD CONSTRAINT "fk_movement_destination" FOREIGN KEY ("id_destination_warehouse") REFERENCES "warehouses" ("id_warehouse") ON DELETE RESTRICT ON UPDATE RESTRICT;

ALTER TABLE "inventory_movements" ADD CONSTRAINT "fk_movement_lot" FOREIGN KEY ("id_lot") REFERENCES "product_lots" ("id_lot") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "inventory_movements" ADD CONSTRAINT "fk_movement_responsible" FOREIGN KEY ("id_responsible") REFERENCES "sales_staff" ("id_staff") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "inventory_movements" ADD CONSTRAINT "fk_movement_source" FOREIGN KEY ("id_source_warehouse") REFERENCES "warehouses" ("id_warehouse") ON DELETE RESTRICT ON UPDATE RESTRICT;

ALTER TABLE "organization_fisherman" ADD CONSTRAINT "fk_membership_fisherman" FOREIGN KEY ("id_fisherman") REFERENCES "fishermen" ("id_fisherman") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "organization_fisherman" ADD CONSTRAINT "fk_membership_organization" FOREIGN KEY ("id_organization") REFERENCES "organizations" ("id_organization") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "organization_vessel" ADD CONSTRAINT "fk_link_organization" FOREIGN KEY ("id_organization") REFERENCES "organizations" ("id_organization") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "organization_vessel" ADD CONSTRAINT "fk_link_vessel" FOREIGN KEY ("id_vessel") REFERENCES "vessels" ("id_vessel") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "product_lots" ADD CONSTRAINT "fk_lot_catch" FOREIGN KEY ("id_catch") REFERENCES "catches" ("id_catch") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "product_lots" ADD CONSTRAINT "fk_lot_classification" FOREIGN KEY ("id_classification") REFERENCES "product_classifications" ("id_classification") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "quality_inspections" ADD CONSTRAINT "fk_inspection_catch" FOREIGN KEY ("id_catch") REFERENCES "catches" ("id_catch") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "sale_details" ADD CONSTRAINT "fk_detail_catch" FOREIGN KEY ("id_catch") REFERENCES "catches" ("id_catch") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "sale_details" ADD CONSTRAINT "fk_detail_sale" FOREIGN KEY ("id_sale") REFERENCES "sales" ("id_sale") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "sales" ADD CONSTRAINT "fk_sale_buyer" FOREIGN KEY ("id_buyer") REFERENCES "buyers" ("id_buyer") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "sales" ADD CONSTRAINT "fk_sale_manager" FOREIGN KEY ("id_commercial_manager") REFERENCES "sales_staff" ("id_staff") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "sales_audit" ADD CONSTRAINT "fk_audit_detail" FOREIGN KEY ("id_detail") REFERENCES "sale_details" ("id_detail") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "trip_crew" ADD CONSTRAINT "fk_crew_fisherman" FOREIGN KEY ("id_fisherman") REFERENCES "fishermen" ("id_fisherman") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "trip_crew" ADD CONSTRAINT "fk_crew_trip" FOREIGN KEY ("id_trip") REFERENCES "trips" ("id_trip") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "trip_observations" ADD CONSTRAINT "fk_observation_trip" FOREIGN KEY ("id_trip") REFERENCES "trips" ("id_trip") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "trips" ADD CONSTRAINT "fk_trip_coordinator" FOREIGN KEY ("id_coordinator") REFERENCES "sales_staff" ("id_staff") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "trips" ADD CONSTRAINT "fk_trip_organization" FOREIGN KEY ("id_organization") REFERENCES "organizations" ("id_organization") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "trips" ADD CONSTRAINT "fk_trip_vessel" FOREIGN KEY ("id_vessel") REFERENCES "vessels" ("id_vessel") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "trips" ADD CONSTRAINT "fk_trip_zone" FOREIGN KEY ("id_zone") REFERENCES "fishing_zones" ("id_zone") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "users" ADD CONSTRAINT "fk_user_role" FOREIGN KEY ("id_role") REFERENCES "roles" ("id_role") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "users" ADD CONSTRAINT "fk_user_staff" FOREIGN KEY ("id_staff") REFERENCES "sales_staff" ("id_staff") ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE "warehouses" ADD CONSTRAINT "fk_warehouse_organization" FOREIGN KEY ("id_organization") REFERENCES "organizations" ("id_organization") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE INDEX "catch_audit_ix_catch_audit_date" ON "catch_audit" ("id_catch","change_date");

CREATE INDEX "catches_ix_catch_species_landing" ON "catches" ("id_species","landing_date");

CREATE INDEX "catches_ix_catch_trip" ON "catches" ("id_trip");

CREATE INDEX "inventory_movements_fk_movement_source" ON "inventory_movements" ("id_source_warehouse");

CREATE INDEX "inventory_movements_fk_movement_destination" ON "inventory_movements" ("id_destination_warehouse");

CREATE INDEX "inventory_movements_fk_movement_responsible" ON "inventory_movements" ("id_responsible");

CREATE INDEX "inventory_movements_ix_movement_lot_date" ON "inventory_movements" ("id_lot","movement_date");

CREATE INDEX "organization_fisherman_fk_membership_fisherman" ON "organization_fisherman" ("id_fisherman");

CREATE INDEX "organization_vessel_fk_link_vessel" ON "organization_vessel" ("id_vessel");

CREATE INDEX "product_lots_fk_lot_catch" ON "product_lots" ("id_catch");

CREATE INDEX "product_lots_fk_lot_classification" ON "product_lots" ("id_classification");

CREATE INDEX "quality_inspections_ix_inspection_catch_date" ON "quality_inspections" ("id_catch","control_date");

COMMENT ON COLUMN "sale_details"."unit_price" IS 'COP per kilogram';

CREATE INDEX "sale_details_ix_detail_catch_weight" ON "sale_details" ("id_catch","sold_weight_kg");

CREATE INDEX "sales_fk_sale_manager" ON "sales" ("id_commercial_manager");

CREATE INDEX "sales_ix_sale_buyer_date" ON "sales" ("id_buyer","sale_date");

CREATE INDEX "sales_audit_ix_audit_detail_date" ON "sales_audit" ("id_detail","change_date");

CREATE INDEX "trip_crew_ix_crew_fisherman" ON "trip_crew" ("id_fisherman","id_trip");

CREATE INDEX "trip_observations_ix_observation_trip_date" ON "trip_observations" ("id_trip","date_time");

CREATE INDEX "trips_fk_trip_organization" ON "trips" ("id_organization");

CREATE INDEX "trips_fk_trip_coordinator" ON "trips" ("id_coordinator");

CREATE INDEX "trips_ix_trip_vessel_departure" ON "trips" ("id_vessel","departure_date");

CREATE INDEX "trips_ix_trip_zone_return" ON "trips" ("id_zone","return_date");

CREATE INDEX "users_fk_user_role" ON "users" ("id_role");

ALTER SEQUENCE "catch_audit_id_catch_audit_seq" OWNED BY "catch_audit"."id_catch_audit";

ALTER SEQUENCE "inventory_movements_id_movement_seq" OWNED BY "inventory_movements"."id_movement";

ALTER SEQUENCE "sales_audit_id_audit_seq" OWNED BY "sales_audit"."id_audit";

COMMIT;

SELECT 'Carga de tablas y datos completada' AS resultado;
